head.script:
/**
 * @component
 * @componentName exc_slip_gridView
 * @pluginName 
 * @inherit w2:gridView
 * @company
 * @developer
 * @category /webTop/cm/udc/slip
 * @notSupportBrowser 
 * @version
 * @htmlRender
 * @icon
 * @disableIcon
 * @description
 * @width
 * @height
 * @license
 * @imagePath
 * @homepage
 */


scwin.onpageload = function() {

};

scwin.getCompName = function() {
	return 'slip_99_comp_gridView';
};

/**
 * 전장표 인쇄를 위한 데이터를 반환 한다.
 */
scwin.getSlipData = function(curInx, tPageCnt, LPI, CPI, LPI_PER_PIXEL, CPI_PER_PIXEL, MARGIN_LEFT, MARGIN_TOP, baseCompID) {

	var rtnArr = [];
	var $baseElm = $('#' + baseCompID);
	var baseOffset = $baseElm.offset();
	var pageSize = exc_slip_gridView.getUserData('PAGE_SIZE');
	var sValArr  = exc_slip_gridView.getAllDisplayJSON();
	var rowJson, sVal, $elm, _offset, _align, _width, colPos, rowPos;
	var iCnt1 = (curInx + 1) * pageSize;

	if (iCnt1 > exc_slip_gridView._dataList.getTotalRow()) iCnt1 = exc_slip_gridView._dataList.getTotalRow();

	for (var idx1 = curInx * pageSize, inx = 0; idx1 < iCnt1; idx1++, inx++) {

		rowJson = sValArr[idx1];

		for (var idx2 = 0, iCnt2 = exc_slip_gridView.getTotalCol(); idx2 < iCnt2; idx2++) {

			sVal = (rowJson[exc_slip_gridView.getColumnID(idx2)] || '').replaceAll('&nbsp;', ' ');
			sVal = sVal.replaceAll('\u00A0', ' ');

			if (sVal == '') continue;

			$elm = $('#' + exc_slip_gridView.getID() + '_cell_' + inx + '_' + idx2);

			_offset = $elm.offset();
			_align  = $elm.css('text-align');
			_width  = $elm.width();

			_width = Math.round(parseInt(_width, 10) / CPI_PER_PIXEL);

			colPos = Math.round((_offset.left - baseOffset.left - MARGIN_LEFT) / CPI_PER_PIXEL);

			if (_align == 'center') {
				colPos = colPos + (_width >> 1) - (WebSquare.util.getByteLength(sVal) >> 1);
			} else if (_align == 'right') {
				colPos = colPos + _width - WebSquare.util.getByteLength(sVal);
			}

			rtnArr.push({
				'column'     : colPos + 1,
				'line'       : Math.round((_offset.top - baseOffset.top - MARGIN_TOP) / LPI_PER_PIXEL),
				'data'       : sVal
			});

			console.log(rtnArr[rtnArr.length - 1]);

		}

	}

	return rtnArr;
};

scwin.getDataList = function() {
    const propValue = this.options?.dataList || null;

    // gridView 속성 중 dataList가 없는 경우 (빈 값도 허용)
    if (propValue === null || propValue === undefined) { 
        return; 
    }

    // 만약 dataList가 있더라도 data: prefix를 붙이지 않는 경우도 undefined를 반환한다.
    if (!propValue.startsWith('data:')) {
        return;
    }

    const dataList = propValue.replace('data:', ''); // data:를 제거한 실제 id만 추출한다.

    // [수정] EXC scope에서는 부모 페이지의 dataList를 찾을 수 없으므로 $p.top() 사용
    return $p.getComponentById(dataList) || null;
}
